1	package world
2	
3	import "fmt"
4	
5	// RuleError 表示数据或提交违反了世界规则。
6	type RuleError struct {
7		Reason string
8	}
9	
10	func (e *RuleError) Error() string { return "world: " + e.Reason }
11	
12	func ruleErrorf(format string, args ...any) error {
13		return &RuleError{Reason: fmt.Sprintf(format, args...)}
14	}
15	
16	// validateRules 校验规则本身：非空版本、地点不重复且非空标识、
17	// 连通关系只引用已有地点、物品不重复、携带上限非负。
18	func validateRules(r Rules) error {
19		if r.Version == "" {
20			return ruleErrorf("规则版本不能为空")
21		}
22		locs := make(map[string]struct{}, len(r.Locations))
23		for _, l := range r.Locations {
24			if l == "" {
25				return ruleErrorf("地点标识不能为空")
26			}
27			if _, ok := locs[l]; ok {
28				return ruleErrorf("地点标识重复: %q", l)
29			}
30			locs[l] = struct{}{}
31		}
32		for i, e := range r.Edges {
33			if _, ok := locs[e.From]; !ok {
34				return ruleErrorf("连通关系 %d 引用了不存在的地点: %q", i, e.From)
35			}
36			if _, ok := locs[e.To]; !ok {
37				return ruleErrorf("连通关系 %d 引用了不存在的地点: %q", i, e.To)
38			}
39		}
40		kinds := make(map[string]struct{}, len(r.ItemKinds))
41		for _, k := range r.ItemKinds {
42			if k == "" {
43				return ruleErrorf("物品种类标识不能为空")
44			}
45			if _, ok := kinds[k]; ok {
46				return ruleErrorf("物品种类重复: %q", k)
47			}
48			kinds[k] = struct{}{}
49		}
50		for who, limit := range r.CarryLimits {
51			if limit < 0 {
52				return ruleErrorf("角色 %q 的携带上限不能为负: %d", who, limit)
53			}
54		}
55		return nil
56	}
57	
58	func (r Rules) adjacent(from, to string) bool {
59		for _, e := range r.Edges {
60			if (e.From == from && e.To == to) || (e.From == to && e.To == from) {
61				return true
62			}
63		}
64		return false
65	}
66	
67	// validateCharacters 校验角色集合：标识不重复、位于已有地点；
68	// 物品种类合法、数量非负、不重复，总量不超过携带上限。
69	func validateCharacters(chars []Character, r Rules) error {
70		locSet := make(map[string]struct{}, len(r.Locations))
71		for _, l := range r.Locations {
72			locSet[l] = struct{}{}
73		}
74		kindSet := make(map[string]struct{}, len(r.ItemKinds))
75		for _, k := range r.ItemKinds {
76			kindSet[k] = struct{}{}
77		}
78		ids := make(map[string]struct{}, len(chars))
79		for _, c := range chars {
80			if c.ID == "" {
81				return ruleErrorf("角色标识不能为空")
82			}
83			if _, ok := ids[c.ID]; ok {
84				return ruleErrorf("角色标识重复: %q", c.ID)
85			}
86			ids[c.ID] = struct{}{}
87			if _, ok := locSet[c.Location]; !ok {
88				return ruleErrorf("角色 %q 位于不存在的地点: %q", c.ID, c.Location)
89			}
90			seen := make(map[string]struct{}, len(c.Items))
91			total := 0
92			for _, it := range c.Items {
93				if _, ok := kindSet[it.Item]; !ok {
94					return ruleErrorf("角色 %q 持有规则不允许的物品: %q", c.ID, it.Item)
95				}
96				if _, dup := seen[it.Item]; dup {
97					return ruleErrorf("角色 %q 的物品 %q 重复列出", c.ID, it.Item)
98				}
99				seen[it.Item] = struct{}{}
100				if it.Count < 0 {
101					return ruleErrorf("角色 %q 的物品 %q 数量不能为负: %d", c.ID, it.Item, it.Count)
102				}
103				total += it.Count
104			}
105			limit, hasLimit := r.CarryLimits[c.ID]
106			if hasLimit && total > limit {
107				return ruleErrorf("角色 %q 携带总量 %d 超过上限 %d", c.ID, total, limit)
108			}
109		}
110		return nil
111	}
112	
