252				continue
253			}
254			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
255				lastReason = (&VersionRejectedError{
256					Record:  id,
257					Version: env.State.Rules.Version,
258				}).Error()
259				continue
260			}
261			return env, nil
262		}
263	
264		if lastReason == "" {
265			lastReason = "槽中没有任何可确认归属的历史记录"
266		}
267		return nil, &UnrecoverableError{Reason: lastReason}
268	}
