1	package world
2	
3	import (
4		"crypto/rand"
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"io"
10		"os"
11		"path/filepath"
12	)
13	
14	// RecordID 是一次成功保存产生的、在同一存档目录内唯一的记录标识。
15	type RecordID string
16	
17	// archiveFormatVersion 是存档目录布局版本，写入目录标记中。
18	const archiveFormatVersion = 1
19	
20	// envelope 是记录文件在磁盘上的完整编码。
21	type envelope struct {
22		// Format 是记录格式版本。
23		Format int `json:"format"`
24		// ID 是本条记录的唯一标识。
25		ID RecordID `json:"id"`
26		// Parent 是父记录标识；直接建立的槽首条记录为空。
27		Parent RecordID `json:"parent,omitempty"`
28		// SlotFirst 标记本条记录是否为其所在槽的首条记录
29		// （直接建立的根记录，或从其他槽分出的分支记录）。
30		SlotFirst bool `json:"slotFirst"`
31		// Checksum 是对（格式版本、ID、父记录、首记录标记、完整世界状态）
32		// 计算出的内容校验和，因此父记录关系也被纳入校验。
33		Checksum string `json:"checksum"`
34		// State 是完整世界数据：种子、规则与全部状态。
35		State State `json:"state"`
36	}
37	
38	// checksumPayload 是参与校验和计算的规范内容。
39	type checksumPayload struct {
40		Format    int      `json:"format"`
41		ID        RecordID `json:"id"`
42		Parent    RecordID `json:"parent"`
43		SlotFirst bool     `json:"slotFirst"`
44		State     State    `json:"state"`
45	}
46	
47	func computeChecksum(e *envelope) string {
48		p := checksumPayload{
49			Format:    e.Format,
50			ID:        e.ID,
51			Parent:    e.Parent,
52			SlotFirst: e.SlotFirst,
53			State:     e.State,
54		}
55		// encoding/json 对 map 按键排序输出，同一状态总是得到相同字节。
56		b, _ := json.Marshal(p)
57		sum := sha256.Sum256(b)
58		return hex.EncodeToString(sum[:])
59	}
60	
61	// newRecordID 产生目录内唯一的记录标识。
62	func newRecordID() (RecordID, error) {
63		var b [16]byte
64		if _, err := rand.Read(b[:]); err != nil {
65			return "", err
66		}
67		return RecordID("r" + hex.EncodeToString(b[:])), nil
68	}
69	
70	func recordPath(dir string, id RecordID) string {
71		return filepath.Join(dir, "records", string(id)+".json")
72	}
73	
74	// writeRecord 将一条记录以“先临时文件后原子改名”的方式落盘，
75	// 并校验目标文件名此前不存在，保证记录标识不会复用或混写。
76	func writeRecord(slotDir string, e *envelope) error {
77		final := recordPath(slotDir, e.ID)
78		data, err := json.MarshalIndent(e, "", "  ")
79		if err != nil {
80			return err
81		}
82	
83		// O_EXCL：即便极小概率撞到重复 ID，也绝不会覆盖别的记录。
84		f, err := os.OpenFile(final+".tmp",
85			os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
86		if err != nil {
87			return err
88		}
89		tmpName := f.Name()
90		clean := true
91		defer func() {
92			if clean {
93				os.Remove(tmpName)
94			}
95		}()
96	
97		if _, err := f.Write(data); err != nil {
98			f.Close()
99			return err
100		}
101		if err := f.Sync(); err != nil {
102			f.Close()
103			return err
104		}
105		if err := f.Close(); err != nil {
106			return err
107		}
108		if err := os.Rename(tmpName, final); err != nil {
109			return err
110		}
111		clean = false
112		if err := syncDir(filepath.Dir(final)); err != nil {
113			return err
114		}
115		return nil
116	}
117	
118	// loadRecord 读取并解析一条记录文件，但不做校验。
119	func loadRecord(path string) (*envelope, error) {
120		f, err := os.Open(path)
